/// The group headers currently visible in a workspace-symbols window — one `Label` per file,
/// with only the expanded group's `Symbol` rows interleaved. Both merges landing ⇔ both files'
/// headers showing, which is how the scope test knows a fan-out has settled.
fn symbol_group_labels(items: &[PickerItem]) -> Vec<String> {
    items
        .iter()
        .filter_map(|i| match i {
            PickerItem::Group {
                header: GroupHeader::Label { label },
                ..
            } => Some(label.clone()),
            _ => None,
        })
        .collect()
}

/// Poll the workspace-symbols view (`PickerReset::Keep`) until `done` accepts its items —
/// the fan-out merges asynchronously, and `send_request` eats the push notifications.
async fn poll_symbol_view(ws: &mut Ws, done: impl Fn(&[PickerItem]) -> bool) -> Vec<PickerItem> {
    for _ in 0..100 {
        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        let view = send_request::<PickerView>(
            ws,
            &PickerViewParams {
                    view_id: None,
                reset: PickerReset::Keep,
                ..view_params(PickerKind::WorkspaceSymbols)
            },
        )
        .await;
        if let Some(items) = view.update.as_ref().and_then(|u| u.items.clone()) {
            if done(&items) {
                return items;
            }
        }
    }
    panic!("workspace-symbols view never reached the expected state");
}

/// The `Dir` chip prunes the LSP fan-out: a project whose server root is disjoint from every scoped
/// directory is not asked at all, not merely filtered out afterwards. And once a fan-out has
/// settled, a filter-only change whose admitted servers it covers reuses the accumulated candidates
/// — the servers never see filters, so re-asking would wipe and refetch the exact answers already
/// held.
#[tokio::test]
async fn workspace_symbol_dir_scope_prunes_the_fanout_and_filter_changes_reuse_it() {
    use aether_server::DummyLspConfig;
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    let dir = lay_out(&[
        ("frontend/package.json", "{}"),
        ("frontend/src/app.ts", "function front_helper() {}\n"),
        ("backend/Cargo.toml", "[package]\nname = \"b\"\n"),
        ("backend/src/main.rs", "fn back_helper() {}\n"),
    ]);
    let front_asked = Arc::new(AtomicUsize::new(0));
    let back_asked = Arc::new(AtomicUsize::new(0));
    let front = DummyLspConfig {
        workspace_symbols: vec![dummy_symbol(
            "front_helper",
            &dir.path().join("frontend/src/app.ts"),
            0,
            9,
        )],
        symbol_query_filter: true,
        symbol_requests: Some(front_asked.clone()),
        ..Default::default()
    };
    let back = DummyLspConfig {
        workspace_symbols: vec![dummy_symbol(
            "back_helper",
            &dir.path().join("backend/src/main.rs"),
            0,
            3,
        )],
        symbol_query_filter: true,
        symbol_requests: Some(back_asked.clone()),
        ..Default::default()
    };
    let server = aether_server::spawn_for_test_with_projects(
        "syms-scope",
        vec![dir.path().to_path_buf()],
        vec![
            aether_server::ProjectRef {
                root_index: 0,
                relative_path: "frontend".into(),
                language: Some("typescript".into()),
            },
            aether_server::ProjectRef {
                root_index: 0,
                relative_path: "backend".into(),
                language: Some("rust".into()),
            },
        ],
        vec![("typescript".into(), front), ("rust".into(), back)],
    )
    .await
    .unwrap();
    await_lsp_state(&server, "both pinned servers", |v| {
        v.len() == 2 && v.iter().all(|s| s.ready && s.pinned)
    })
    .await;

    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "syms-scope".into(),
            open_last: false,
        },
    )
    .await;
    let query = |generation: u64, filters: PickerFilters| PickerQueryParams {
        kind: PickerKind::WorkspaceSymbols,
        query: "helper".into(),
        generation,
        filters,
    };
    let scope_frontend = PickerFilters {
        directories: vec![ScopedPath {
            path_index: 0,
            relative_path: "frontend".into(),
            is_file: false,
        }],
        ..Default::default()
    };

    // Scoped from the start: only the frontend project's server is asked.
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::WorkspaceSymbols)).await;
    let _: () = send_request::<PickerQuery>(&mut ws, &query(1, scope_frontend.clone())).await;
    let items = poll_symbol_view(&mut ws, |items| !items.is_empty()).await;
    assert_eq!(symbol_group_labels(&items), vec!["frontend/src/app.ts"]);
    // Wait for the fan-out to be finished rather than sleeping past it: the assertion below is
    // that the backend server was *never asked*, and that is only exact once every query this
    // fan-out was going to spawn has run.
    settled(&server).await;
    assert_eq!(front_asked.load(Ordering::SeqCst), 1);
    assert_eq!(
        back_asked.load(Ordering::SeqCst),
        0,
        "a scoped-out project's server must not be asked at all"
    );

    // Dropping the scope admits a server the recorded fan-out never asked — full re-fan-out.
    let _: () = send_request::<PickerQuery>(&mut ws, &query(2, PickerFilters::default())).await;
    let items = poll_symbol_view(&mut ws, |items| symbol_group_labels(items).len() == 2).await;
    assert_eq!(
        symbol_group_labels(&items),
        vec!["backend/src/main.rs", "frontend/src/app.ts"],
        "both projects' symbols, grouped by file"
    );
    assert_eq!(front_asked.load(Ordering::SeqCst), 2);
    assert_eq!(back_asked.load(Ordering::SeqCst), 1);

    // A glob chip on the settled fan-out: covered — reranked in place, no LSP traffic, and the
    // answer is synchronous (no polling: the query's reply means the rerank already happened).
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &query(
            3,
            PickerFilters {
                globs: vec!["*.ts".into()],
                ..Default::default()
            },
        ),
    )
    .await;
    let view = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
                view_id: None,
            reset: PickerReset::Keep,
            ..view_params(PickerKind::WorkspaceSymbols)
        },
    )
    .await;
    let items = view.update.and_then(|u| u.items).unwrap_or_default();
    assert_eq!(symbol_group_labels(&items), vec!["frontend/src/app.ts"]);

    // Removing the chip is covered too — the fan-out asked both servers.
    let _: () = send_request::<PickerQuery>(&mut ws, &query(4, PickerFilters::default())).await;
    let view = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
                view_id: None,
            reset: PickerReset::Keep,
            ..view_params(PickerKind::WorkspaceSymbols)
        },
    )
    .await;
    let items = view.update.and_then(|u| u.items).unwrap_or_default();
    assert_eq!(symbol_group_labels(&items).len(), 2);
    assert_eq!(
        (
            front_asked.load(Ordering::SeqCst),
            back_asked.load(Ordering::SeqCst)
        ),
        (2, 1),
        "filter-only changes must not re-ask the servers"
    );
}

/// A server reaching `Ready` while a *scoped* query is live respects the scope: the became-ready
/// re-query (`requery_ready_server`) skips a server the `Dir` chip would have pruned from the
/// fan-out — readiness doesn't change what it can contribute. Dropping the scope afterwards picks
/// the server up through the ordinary re-fan-out (the recorded fan-out doesn't cover it).
#[tokio::test]
async fn ready_server_requery_respects_the_dir_scope() {
    use aether_server::DummyLspConfig;
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    let dir = lay_out(&[
        ("frontend/package.json", "{}"),
        ("frontend/src/app.ts", "function front_helper() {}\n"),
        ("backend/Cargo.toml", "[package]\nname = \"b\"\n"),
        ("backend/src/main.rs", "fn back_helper() {}\n"),
    ]);
    let front_asked = Arc::new(AtomicUsize::new(0));
    let back_asked = Arc::new(AtomicUsize::new(0));
    let front = DummyLspConfig {
        workspace_symbols: vec![dummy_symbol(
            "front_helper",
            &dir.path().join("frontend/src/app.ts"),
            0,
            9,
        )],
        symbol_query_filter: true,
        symbol_requests: Some(front_asked.clone()),
        ..Default::default()
    };
    let back = DummyLspConfig {
        workspace_symbols: vec![dummy_symbol(
            "back_helper",
            &dir.path().join("backend/src/main.rs"),
            0,
            3,
        )],
        symbol_query_filter: true,
        symbol_requests: Some(back_asked.clone()),
        // Still doing its handshake while the scoped query below is typed — the ready-requery
        // path is the only way it could be asked.
        initialize_delay: Some(std::time::Duration::from_millis(700)),
        ..Default::default()
    };
    let server = aether_server::spawn_for_test_with_projects(
        "syms-ready-scope",
        vec![dir.path().to_path_buf()],
        vec![
            aether_server::ProjectRef {
                root_index: 0,
                relative_path: "frontend".into(),
                language: Some("typescript".into()),
            },
            aether_server::ProjectRef {
                root_index: 0,
                relative_path: "backend".into(),
                language: Some("rust".into()),
            },
        ],
        vec![("typescript".into(), front), ("rust".into(), back)],
    )
    .await
    .unwrap();
    await_lsp_state(
        &server,
        "the frontend server (backend still starting)",
        |v| v.iter().any(|s| s.language == "typescript" && s.ready),
    )
    .await;

    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "syms-ready-scope".into(),
            open_last: false,
        },
    )
    .await;
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::WorkspaceSymbols)).await;
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            kind: PickerKind::WorkspaceSymbols,
            query: "helper".into(),
            generation: 1,
            filters: PickerFilters {
                directories: vec![ScopedPath {
                    path_index: 0,
                    relative_path: "frontend".into(),
                    is_file: false,
                }],
                ..Default::default()
            },
        },
    )
    .await;
    let items = poll_symbol_view(&mut ws, |items| !items.is_empty()).await;
    assert_eq!(symbol_group_labels(&items), vec!["frontend/src/app.ts"]);

    // The backend server finishes starting with the scoped query still live. Its re-query must
    // be skipped, not merely have its results filtered out afterwards.
    await_lsp_state(&server, "the backend server", |v| {
        v.iter().any(|s| s.language == "rust" && s.ready)
    })
    .await;
    // The re-query is decided *after* the status flips to Ready, so waiting on readiness alone
    // would race it. The readiness transition counts itself as deferred work, so waiting for the
    // server to go quiet covers the re-query too.
    settled(&server).await;
    assert_eq!(front_asked.load(Ordering::SeqCst), 1);
    assert_eq!(
        back_asked.load(Ordering::SeqCst),
        0,
        "readiness must not bypass the Dir scope"
    );

    // Dropping the scope admits it — the recorded fan-out never asked it, so this re-fans out.
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            kind: PickerKind::WorkspaceSymbols,
            query: "helper".into(),
            generation: 2,
            filters: PickerFilters::default(),
        },
    )
    .await;
    let items = poll_symbol_view(&mut ws, |items| symbol_group_labels(items).len() == 2).await;
    assert_eq!(
        symbol_group_labels(&items),
        vec!["backend/src/main.rs", "frontend/src/app.ts"]
    );
    assert_eq!(back_asked.load(Ordering::SeqCst), 1);
}

/// `Ctrl-j` in the workspace-symbols picker snapshots the shown rows into the jumplist.
/// Regression: `jumplist::capture` had no `WorkspaceSymbols` arm, so every capture answered
/// "Nothing to capture" even with results showing. The stored entries carry their file identity,
/// so the Jumplist picker groups them under real `File` headers (not the root-directory bug the
/// empty-sentinel path once had) and the highlighted row keeps its place.
#[tokio::test]
async fn workspace_symbols_capture_to_the_jumplist() {
    use aether_server::DummyLspConfig;
    let dir = lay_out(&[
        ("Cargo.toml", "[package]\nname = \"p\"\n"),
        ("src/a.rs", "fn helper_one() {}\n"),
        ("src/b.rs", "fn helper_two() {}\n"),
    ]);
    let dummy = DummyLspConfig {
        workspace_symbols: vec![
            dummy_symbol("helper_one", &dir.path().join("src/a.rs"), 0, 3),
            dummy_symbol("helper_two", &dir.path().join("src/b.rs"), 0, 3),
        ],
        symbol_query_filter: true,
        ..Default::default()
    };
    let server = aether_server::spawn_for_test_with_projects(
        "syms-capture",
        vec![dir.path().to_path_buf()],
        vec![project_ref(".")],
        vec![("rust".into(), dummy)],
    )
    .await
    .unwrap();
    await_lsp_state(&server, "the pinned server", |v| v.len() == 1 && v[0].ready).await;
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "syms-capture".into(),
            open_last: false,
        },
    )
    .await;
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::WorkspaceSymbols)).await;
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            kind: PickerKind::WorkspaceSymbols,
            query: "helper".into(),
            generation: 1,
            filters: Default::default(),
        },
    )
    .await;
    let items = poll_symbol_view(&mut ws, |items| symbol_group_labels(items).len() == 2).await;

    // Groups open collapsed, so open the first one to get a symbol row on screen.
    let Some(PickerItem::Group { header, .. }) = items.first().cloned() else {
        panic!("the window leads with a group header, got {items:?}");
    };
    let _: PickerSetGroupResult = send_request::<PickerSetGroup>(
        &mut ws,
        &PickerSetGroupParams {
            kind: PickerKind::WorkspaceSymbols,
            action: PickerGroupAction::Expand { header },
        },
    )
    .await;
    let items = send_request::<PickerView>(
        &mut ws,
        &PickerViewParams {
                view_id: None,
            reset: PickerReset::Keep,
            ..view_params(PickerKind::WorkspaceSymbols)
        },
    )
    .await
    .update
    .and_then(|u| u.items)
    .expect("a Keep re-view carries its window");

    // Capture with the first visible symbol row highlighted (the expanded group's row).
    let item = items
        .iter()
        .find(|i| matches!(i, PickerItem::Symbol { .. }))
        .cloned()
        .expect("a symbol row in the expanded group");
    let captured: Option<JumplistCaptureResult> = send_request::<JumplistCapture>(
        &mut ws,
        &JumplistCaptureParams {
            kind: PickerKind::WorkspaceSymbols,
            item,
        },
    )
    .await;
    let captured = captured.expect("the workspace-symbols picker captures");
    assert_eq!(captured.total, 2, "both shown symbols snapshot");
    assert_eq!(
        captured.index, 0,
        "the highlighted row (first group's symbol) leads the normalized list"
    );

    // The Jumplist picker shows the entries under real per-file headers.
    let view = send_request::<PickerView>(&mut ws, &view_params(PickerKind::Jumplist)).await;
    let rows = view.update.and_then(|u| u.items).unwrap_or_default();
    let files: Vec<String> = rows
        .iter()
        .filter_map(|i| match i {
            PickerItem::Group {
                header: GroupHeader::File { relative_path, .. },
                ..
            } => Some(relative_path.clone()),
            _ => None,
        })
        .collect();
    assert_eq!(
        files,
        vec!["src/a.rs", "src/b.rs"],
        "entries grouped by their real relative paths"
    );
}

/// The server matched it, so it shows — even when our own fuzzy matcher wouldn't. This is what
/// keeps rust-analyzer's `#`/`*` query conventions working: a literal fuzzy match of `foo#` against
/// symbol names fails every row, and filtering on that would empty a picker that worked at the
/// server.
#[tokio::test]
async fn workspace_symbols_keep_server_matches_our_matcher_would_reject() {
    use aether_server::DummyLspConfig;
    let dir = lay_out(&[
        ("Cargo.toml", "[package]\nname = \"p\"\n"),
        ("src/main.rs", "fn main() {}\n"),
    ]);
    let target = dir.path().join("src/main.rs");
    let dummy = DummyLspConfig {
        workspace_symbols: vec![dummy_symbol("totally_unrelated", &target, 0, 3)],
        // The server ignores the query entirely — standing in for a server whose match rules differ
        // from ours.
        symbol_query_filter: false,
        ..Default::default()
    };
    let server = aether_server::spawn_for_test_with_projects(
        "syms-loose",
        vec![dir.path().to_path_buf()],
        vec![project_ref(".")],
        vec![("rust".into(), dummy)],
    )
    .await
    .unwrap();
    await_lsp_state(&server, "the pinned server", |v| v.len() == 1 && v[0].ready).await;
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "syms-loose".into(),
            open_last: false,
        },
    )
    .await;

    // `zzz#` matches nothing about `totally_unrelated` under any fuzzy rule.
    let rows = workspace_symbol_rows(&mut ws, "zzz#").await;
    assert_eq!(rows.len(), 1, "a server match survives our rerank");
    let PickerItem::Symbol {
        name,
        match_indices,
        ..
    } = &rows[0]
    else {
        panic!("expected a Symbol row");
    };
    assert_eq!(name, "totally_unrelated");
    assert!(
        match_indices.is_empty(),
        "unmatched by us, so nothing to highlight",
    );
}

/// Symbols spread across files render one group per file — files ordered by their best match,
/// each file's rows contiguous, the server-matched-only file trailing — and group stepping
/// reaches every file. Flat score ordering used to interleave files, which rendered duplicate
/// headers and (a group key resolves to its *first* run) snapped `set_group` back to the first
/// copy, leaving later groups unreachable.
#[tokio::test]
async fn workspace_symbol_groups_stay_contiguous_and_step_to_every_file() {
    use aether_server::DummyLspConfig;
    let dir = lay_out(&[
        ("Cargo.toml", "[package]\nname = \"p\"\n"),
        ("src/a_early.rs", "fn bag_of_roots() {}\n"),
        ("src/m_mid.rs", "fn unrelated() {}\n"),
        ("src/z_late.rs", "fn brotli_footer() {}\nfn boot() {}\n"),
    ]);
    let early = dir.path().join("src/a_early.rs");
    let mid = dir.path().join("src/m_mid.rs");
    let late = dir.path().join("src/z_late.rs");
    let dummy = DummyLspConfig {
        // For the query "boot": the consecutive "boot" far outscores the scattered matches, so
        // best-match ordering must put the alphabetically-last file first; "unrelated" is a
        // server match our matcher rejects, so its file trails as the never-filtered group.
        workspace_symbols: vec![
            dummy_symbol("bag_of_roots", &early, 0, 3),
            dummy_symbol("unrelated", &mid, 0, 3),
            dummy_symbol("brotli_footer", &late, 0, 3),
            dummy_symbol("boot", &late, 1, 3),
        ],
        symbol_query_filter: false,
        ..Default::default()
    };
    let server = aether_server::spawn_for_test_with_projects(
        "syms-groups",
        vec![dir.path().to_path_buf()],
        vec![project_ref(".")],
        vec![("rust".into(), dummy)],
    )
    .await
    .unwrap();
    await_lsp_state(&server, "the pinned server", |v| v.len() == 1 && v[0].ready).await;
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "syms-groups".into(),
            open_last: false,
        },
    )
    .await;

    let view = |reset| PickerViewParams {
            view_id: None,
        reset,
        ..view_params(PickerKind::WorkspaceSymbols)
    };
    let _ = send_request::<PickerView>(&mut ws, &view(PickerReset::All)).await;
    let _: () = send_request::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            kind: PickerKind::WorkspaceSymbols,
            query: "boot".into(),
            generation: 1,
            filters: Default::default(),
        },
    )
    .await;
    // The fan-out is spawned, so poll the view until the merge lands (one server, one batch).
    let mut items = Vec::new();
    for _ in 0..100 {
        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        let view = send_request::<PickerView>(&mut ws, &view(PickerReset::Keep)).await;
        if let Some(got) = view.update.and_then(|u| u.items).filter(|v| !v.is_empty()) {
            items = got;
            break;
        }
    }

    // Row space: one collapsed header per file, best-match file first, never-filtered file last —
    // each file exactly once.
    let headers = |items: &[PickerItem]| {
        items
            .iter()
            .filter_map(|item| match item {
                PickerItem::Group {
                    header: GroupHeader::Label { label },
                    count,
                    expanded,
                } => Some((label.clone(), *count, *expanded)),
                _ => None,
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        headers(&items),
        vec![
            ("src/z_late.rs".to_string(), 2, false),
            ("src/a_early.rs".to_string(), 1, false),
            ("src/m_mid.rs".to_string(), 1, false),
        ],
        "one group per file: best match first, never-filtered file last"
    );
    assert!(
        items.iter().all(|i| matches!(i, PickerItem::Group { .. })),
        "collapsed groups show no symbol rows: {items:?}"
    );

    // Opening the best-match run puts its symbols inline, best row first.
    let Some(PickerItem::Group { header, .. }) = items.first().cloned() else {
        unreachable!("checked above");
    };
    let _: PickerSetGroupResult = send_request::<PickerSetGroup>(
        &mut ws,
        &PickerSetGroupParams {
            kind: PickerKind::WorkspaceSymbols,
            action: PickerGroupAction::Expand { header },
        },
    )
    .await;
    let items = send_request::<PickerView>(&mut ws, &view(PickerReset::Keep))
        .await
        .update
        .and_then(|u| u.items)
        .expect("a Keep re-view carries its window");
    assert_eq!(
        headers(&items),
        vec![
            ("src/z_late.rs".to_string(), 2, true),
            ("src/a_early.rs".to_string(), 1, false),
            ("src/m_mid.rs".to_string(), 1, false),
        ]
    );
    let names: Vec<String> = items
        .iter()
        .filter_map(|i| match i {
            PickerItem::Symbol { name, .. } => Some(name.clone()),
            _ => None,
        })
        .collect();
    assert_eq!(names, vec!["boot", "brotli_footer"]);

    // Group stepping visits each run once and stops at the end — no snap-back to a duplicate.
    let step = PickerSetGroupParams {
        kind: PickerKind::WorkspaceSymbols,
        action: PickerGroupAction::Step {
            direction: Direction::Forward,
            expand: false,
        },
    };
    let r: PickerSetGroupResult = send_request::<PickerSetGroup>(&mut ws, &step).await;
    assert_eq!(
        r.run.map(|r| r.header_row),
        Some(3),
        "first step lands on a_early.rs, below the open run's two symbol rows"
    );
    let r: PickerSetGroupResult = send_request::<PickerSetGroup>(&mut ws, &step).await;
    assert_eq!(
        r.run.map(|r| r.header_row),
        Some(4),
        "second step lands on m_mid.rs"
    );
    let r: PickerSetGroupResult = send_request::<PickerSetGroup>(&mut ws, &step).await;
    assert!(r.run.is_none(), "stepping off the last group is a no-op");
}

/// A query no server matches still settles: the merge that completes the fan-out must push
/// `ticking: false` even though it contributed nothing. Without the completion accounting no
/// push ever followed the `ticking` one and the client spun on "Searching projects…" forever.
#[tokio::test]
async fn workspace_symbols_settle_when_no_server_matches() {
    use aether_server::DummyLspConfig;
    let dir = lay_out(&[
        ("Cargo.toml", "[package]\nname = \"p\"\n"),
        ("src/main.rs", "fn main() {}\nfn helper_one() {}\n"),
    ]);
    let target = dir.path().join("src/main.rs");
    let dummy = DummyLspConfig {
        workspace_symbols: vec![dummy_symbol("helper_one", &target, 1, 3)],
        symbol_query_filter: true,
        ..Default::default()
    };
    let server = aether_server::spawn_for_test_with_projects(
        "syms-empty",
        vec![dir.path().to_path_buf()],
        vec![project_ref(".")],
        vec![("rust".into(), dummy)],
    )
    .await
    .unwrap();
    await_lsp_state(&server, "the pinned server", |v| v.len() == 1 && v[0].ready).await;
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "syms-empty".into(),
            open_last: false,
        },
    )
    .await;
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::WorkspaceSymbols)).await;
    let ((), mut updates) = send_request_collecting_updates::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            kind: PickerKind::WorkspaceSymbols,
            query: "zzzzzz".into(),
            generation: 1,
            filters: Default::default(),
        },
    )
    .await;
    // The settling push — the only server answered with nothing — may have raced the response
    // either way; keep reading until it shows. Gate on the query's generation so the view's
    // initial (generation-0, also non-ticking) push can't satisfy the assertion vacuously.
    let settled = loop {
        if let Some(u) = updates.iter().find(|u| u.generation == 1 && !u.ticking) {
            break u.clone();
        }
        updates.push(
            expect_notification_within::<PickerUpdate>(&mut ws, std::time::Duration::from_secs(2))
                .await,
        );
    };
    assert_eq!(settled.total_matches, 0);
    assert!(
        settled.items.as_ref().is_some_and(|i| i.is_empty()),
        "the settling push carries the (empty) window, not a count-only tick"
    );
}

/// An empty fan-out — the pinned server doesn't advertise `workspace/symbol` — settles in the
/// query's own push. Marking it `ticking` would strand the client: nothing is in flight, so
/// nothing would ever clear it.
#[tokio::test]
async fn workspace_symbols_with_no_capable_server_settle_immediately() {
    use aether_server::DummyLspConfig;
    let dir = lay_out(&[
        ("Cargo.toml", "[package]\nname = \"p\"\n"),
        ("src/main.rs", "fn main() {}\n"),
    ]);
    // No `workspace_symbols` → the handshake doesn't advertise `workspaceSymbolProvider`, so the
    // pinned server is excluded from the fan-out.
    let dummy = DummyLspConfig::default();
    let server = aether_server::spawn_for_test_with_projects(
        "syms-none",
        vec![dir.path().to_path_buf()],
        vec![project_ref(".")],
        vec![("rust".into(), dummy)],
    )
    .await
    .unwrap();
    await_lsp_state(&server, "the pinned server", |v| v.len() == 1 && v[0].ready).await;
    let mut ws = Ws::connect(&server).await;
    let _act: WorkspaceActivateResult = send_request::<WorkspaceActivate>(
        &mut ws,
        &WorkspaceActivateParams {
            worktrees: None,
            name: "syms-none".into(),
            open_last: false,
        },
    )
    .await;
    let _ = send_request::<PickerView>(&mut ws, &view_params(PickerKind::WorkspaceSymbols)).await;
    let ((), mut updates) = send_request_collecting_updates::<PickerQuery>(
        &mut ws,
        &PickerQueryParams {
            kind: PickerKind::WorkspaceSymbols,
            query: "helper".into(),
            generation: 1,
            filters: Default::default(),
        },
    )
    .await;
    while !updates.iter().any(|u| u.generation == 1) {
        updates.push(
            expect_notification_within::<PickerUpdate>(&mut ws, std::time::Duration::from_secs(2))
                .await,
        );
    }
    for u in updates.iter().filter(|u| u.generation == 1) {
        assert!(!u.ticking, "an empty fan-out must not promise answers");
        assert!(
            u.items.is_some(),
            "the settled push carries the (empty) window"
        );
    }
}

/// Poll until `f` holds against the server's LSP state, or fail after ~2s. Server startup is a
/// spawned handshake, so every project assertion has to wait for it rather than assume it landed.
async fn await_lsp_state(
    server: &aether_server::ServerHandle,
    what: &str,
    f: impl Fn(&aether_server::LspManagerView) -> bool,
) {
    for _ in 0..200 {
        {
            let s = server.state.lock().await;
            if f(&aether_server::lsp_view(&s)) {
                return;
            }
        }
        tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    }
    let s = server.state.lock().await;
    panic!(
        "timed out waiting for {what}; servers = {:?}",
        aether_server::lsp_view(&s)
    );
}

